const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');
const {applyPatch}=require('../../scripts/patch-docusaurus.cjs');const spec=require('../../patches/docusaurus-theme-common-3.10.1.json');const root=path.resolve(__dirname,'../..');
function fixture(callback){const temp=fs.mkdtempSync(path.join(root,'qa/search/patch-fixture-'));try{const pkg=path.join(temp,'node_modules',spec.package);fs.mkdirSync(pkg,{recursive:true});fs.writeFileSync(path.join(pkg,'package.json'),JSON.stringify({name:spec.package,version:spec.version}));for(const file of spec.files){let data=fs.readFileSync(path.join(root,'node_modules',spec.package,file.path),'utf8');for(const r of [...file.replacements].reverse())if(data.includes(r.after))data=data.replace(r.after,r.before);const target=path.join(pkg,file.path);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,data);}callback(temp,pkg);}finally{fs.rmSync(temp,{recursive:true,force:true});}}
test('Patch applies to pristine dependency, is idempotent, and installs the lifecycle guard',()=>fixture((temp,pkg)=>{assert.equal(applyPatch(temp),2);assert.equal(applyPatch(temp),0);const code=fs.readFileSync(path.join(pkg,'lib/hooks/useCodeWordWrap.js'),'utf8');assert(code.includes('if (!codeBlock)'));assert(!code.includes('sourceMappingURL='));}));
test('Version mismatch fails closed without modifying dependency files',()=>fixture((temp,pkg)=>{const file=path.join(pkg,spec.files[0].path),before=fs.readFileSync(file);fs.writeFileSync(path.join(pkg,'package.json'),JSON.stringify({name:spec.package,version:'3.10.2'}));assert.throws(()=>applyPatch(temp),/requires.*3\.10\.1/);assert.deepEqual(fs.readFileSync(file),before);}));
test('Unknown content in either file prevents all writes',()=>fixture((temp,pkg)=>{const first=path.join(pkg,spec.files[0].path),before=fs.readFileSync(first);fs.appendFileSync(path.join(pkg,spec.files[1].path),'\n// unrelated change\n');assert.throws(()=>applyPatch(temp),/unknown content/);assert.deepEqual(fs.readFileSync(first),before);}));
test('Guard cancels only detached-node measurement and preserves width/style behavior',()=>{const code=fs.readFileSync(path.join(root,'node_modules',spec.package,'lib/hooks/useCodeWordWrap.js'),'utf8');let patched=code;for(const r of spec.files[1].replacements)patched=patched.replace(r.before,r.after);const body=patched.match(/const updateCodeIsScrollable = useCallback\(\(\) => \{([\s\S]*?)\n    \}, \[codeBlockRef\]\);/)[1];const measure=new Function('codeBlockRef','setIsCodeScrollable',body);let updates=[];measure({current:null},v=>updates.push(v));assert.deepEqual(updates,[]);for(const [scrollWidth,clientWidth,styled,expected] of [[120,100,false,true],[100,100,false,false],[100,100,true,true]]){measure({current:{scrollWidth,clientWidth,querySelector:()=>({hasAttribute:()=>styled})}},v=>updates.push(v));assert.equal(updates.at(-1),expected);}});
